  const options = {
    hostname: domain,
    port: 443,
    path: entry,
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
  };

  const req = https.request(options, (resp) => {
    let data = '';
    // A chunk of data has been received.
    resp.on('data', (chunk) => {
      data += chunk;
